"""R0 service selection: only a verified venv redirector may be collapsed."""

import base64
import copy
import hashlib
import json
import xml.etree.ElementTree as ET

import pytest

from scripts import ci_journey as journey


@pytest.fixture
def r0_pair(tmp_path):
    fixture = journey.ROOT / "tests/fixtures/release0/services/task.xml"
    # The checked-in service is generated by the genuine frozen R0 Agent.
    sums = (fixture.parents[1] / "SHA256SUMS").read_text()
    assert f"{hashlib.sha256(fixture.read_bytes()).hexdigest()}  services/task.xml" in sums
    action = ET.fromstring(fixture.read_bytes()).find(".//{*}Actions/{*}Exec")
    tail = " " + action.find("{*}Arguments").text
    assert action.find("{*}Command").text.endswith(r"py\Scripts\pythonw.exe")
    version = tmp_path / "versions" / "r0" / "version.json"
    scripts = version.parent / "py" / "Scripts"
    scripts.mkdir(parents=True)
    launcher = scripts / "pythonw.exe"
    launcher.write_bytes(b"venv launcher")
    (scripts.parent / "pyvenv.cfg").write_text("home = C:\\Python311\n", encoding="utf-8")
    child_image = r"C:\Python311\pythonw.exe"
    rows = [
        {"ProcessId": 8068, "ParentProcessId": 42, "ExecutablePath": str(launcher),
         "CommandLine": f'"{launcher}"{tail}', "Birth": "100"},
        {"ProcessId": 4032, "ParentProcessId": 8068, "ExecutablePath": child_image,
         "CommandLine": f'"{child_image}"{tail}', "Birth": "200"},
    ]
    return version, rows, {"pid": 4032, "process_birth_id": "windows-creation:200"}


def test_r0_selection_accepts_authentic_service_tail_and_records_snapshot(r0_pair, monkeypatch):
    version, rows, discovery = r0_pair
    calls = []
    monkeypatch.setattr(journey.sys, "platform", "win32")
    monkeypatch.setattr(journey, "healthy", lambda _: discovery)
    def census(command, filename, **kwargs):
        assert journey.windows.EVIDENCE == version.parent / "evidence"
        calls.append((command, filename))
        return json.dumps(rows)
    monkeypatch.setattr(journey.windows, "powershell", census)
    journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")
    assert len(calls) == 1
    assert calls[0][1] == "runtime-owner-selection.json"
    assert all(field in calls[0][0] for field in ("ParentProcessId", "ExecutablePath", "CreationDate"))
    assert "runtime-owner-selection.json" in journey.JOURNEY_EVIDENCE_NAMES
    rows.reverse()
    journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")


@pytest.mark.parametrize("change", [
    "extra", "wrong_selected", "duplicate_pid", "wrong_parent", "missing_parent", "wrong_parent_image",
    "wrong_child_image", "missing_image", "parent_command_image", "child_command_image", "different_tail",
    "missing_birth", "birth_order", "equal_birth", "discovery_birth", "missing_discovery_birth",
    "missing_home", "duplicate_home", "relative_home", "missing_launcher", "linked_launcher",
])
def test_r0_selection_fails_closed(r0_pair, monkeypatch, change):
    version, rows, discovery = r0_pair
    rows, discovery = copy.deepcopy(rows), dict(discovery)
    parent, child = rows
    config = version.parent / "py" / "pyvenv.cfg"
    launcher = version.parent / "py" / "Scripts" / "pythonw.exe"
    if change == "extra": rows.append(dict(child, ProcessId=77))
    elif change == "wrong_selected": discovery["pid"] = 8068
    elif change == "duplicate_pid": child["ProcessId"] = 8068
    elif change == "wrong_parent": child["ParentProcessId"] = 99
    elif change == "missing_parent": del child["ParentProcessId"]
    elif change == "wrong_parent_image": parent["ExecutablePath"] = r"C:\other\pythonw.exe"
    elif change == "wrong_child_image": child["ExecutablePath"] = r"C:\other\pythonw.exe"
    elif change == "missing_image": del parent["ExecutablePath"]
    elif change == "parent_command_image": parent["CommandLine"] = parent["CommandLine"].replace(str(launcher), r"C:\other\pythonw.exe", 1)
    elif change == "child_command_image": child["CommandLine"] = child["CommandLine"].replace(child["ExecutablePath"], r"C:\other\pythonw.exe", 1)
    elif change == "different_tail": child["CommandLine"] += " "
    elif change == "missing_birth": del child["Birth"]
    elif change == "birth_order": parent["Birth"] = "201"
    elif change == "equal_birth": parent["Birth"] = "200"
    elif change == "discovery_birth": discovery["process_birth_id"] = "windows-creation:201"
    elif change == "missing_discovery_birth": del discovery["process_birth_id"]
    elif change == "missing_home": config.write_text("version = 3.11\n")
    elif change == "duplicate_home": config.write_text("home = C:\\Python311\nhome = C:\\Python311\n")
    elif change == "relative_home": config.write_text("home = Python311\n")
    elif change == "missing_launcher": launcher.unlink()
    elif change == "linked_launcher":
        launcher.unlink()
        target = version.parent / "other.exe"
        target.write_bytes(b"other")
        launcher.symlink_to(target)
    monkeypatch.setattr(journey.sys, "platform", "win32")
    monkeypatch.setattr(journey, "healthy", lambda _: discovery)
    monkeypatch.setattr(journey.windows, "powershell", lambda *args, **kwargs: json.dumps(rows))
    with pytest.raises(RuntimeError, match="Expected exactly the selected Runtime owner"):
        journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")


def test_r0_selection_keeps_single_and_other_platform_behavior(r0_pair, monkeypatch):
    version, rows, discovery = r0_pair
    monkeypatch.setattr(journey.sys, "platform", "win32")
    monkeypatch.setattr(journey, "healthy", lambda _: discovery)
    monkeypatch.setattr(journey.windows, "powershell", lambda *args, **kwargs: json.dumps([rows[1]]))
    journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")
    monkeypatch.setattr(journey.sys, "platform", "linux")
    calls = []
    monkeypatch.setattr(journey, "assert_one_runtime", calls.append)
    journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")
    assert calls == [version.parent]


def test_ordinary_windows_census_keeps_existing_powershell_call(r0_pair, monkeypatch):
    version, rows, _ = r0_pair
    monkeypatch.setattr(journey.sys, "platform", "win32")
    def census(command, filename, *, show, timeout):
        assert filename == "runtime-owner-processes.json"
        return json.dumps(rows)
    monkeypatch.setattr(journey.windows, "powershell", census)
    assert journey.runtime_processes(version.parent) == [8068, 4032]


def test_failed_selection_evidence_survives_both_failure_snapshots(r0_pair, tmp_path, monkeypatch):
    version, rows, discovery = r0_pair
    run_root = tmp_path / "run"
    evidence = run_root / "evidence" / "release0-to-release1"
    evidence.mkdir(parents=True)
    # The requested R0 run failed before a task definition was available.
    unit = journey.ROOT / "tests/fixtures/windows-r0-failed-capture/unit-file-before-cleanup.b64"
    unit_bytes = base64.b64decode(unit.read_bytes())
    assert hashlib.sha256(unit_bytes).hexdigest() == "43455756c8329d444713a668423f71131e89d7b19ca4bac3c5c9f68e5ef0f127"
    assert unit_bytes == b"Task Scheduler definition unavailable\r\n"
    (evidence / "unit-file-before-cleanup.txt").write_bytes(unit_bytes)
    journey.write_json(evidence / "journey-result.json", {"scenario": "release0-to-release1", "status": "fail"})
    rows[1]["ParentProcessId"] = 999  # two independent owners must still fail
    monkeypatch.setattr(journey.sys, "platform", "win32")
    monkeypatch.setattr(journey, "healthy", lambda _: discovery)
    def census(command, filename, **kwargs):
        value = json.dumps(rows)
        (journey.windows.EVIDENCE / filename).write_text(value, encoding="utf-8")
        return value
    monkeypatch.setattr(journey.windows, "powershell", census)
    monkeypatch.setattr(journey, "capture_manager_state", lambda *args: None)
    monkeypatch.setattr(journey, "capture_runtime_service_logs", lambda *args: None)
    with pytest.raises(RuntimeError, match=r"found \[8068, 4032\]"):
        journey.assert_release0_runtime(run_root / "data", version, evidence)
    context = journey.read_json(evidence / "runtime-owner-selection-context.json")
    assert context["discovery"] == discovery
    assert context["paths"]["config"]["home_lines"] == [r"home = C:\Python311"]
    assert context["paths"]["launcher"]["is_file"]
    journey.snapshot_failure_evidence(evidence, run_root, run_root / "data", "before-cleanup")
    (version.parent / "py" / "pyvenv.cfg").unlink()
    journey.snapshot_failure_evidence(evidence, run_root, run_root / "data", "after-cleanup")
    for phase in ("before-cleanup", "after-cleanup"):
        staged = run_root / "evidence-upload" / phase
        assert json.loads((staged / "runtime-owner-selection.json").read_text(encoding="utf-8")) == rows
        assert journey.read_json(staged / "runtime-owner-selection-context.json") == context
        assert (staged / "unit-file-before-cleanup.txt").read_bytes() == unit_bytes
        assert (staged / "journey-result.json").is_file()


def test_context_capture_failure_does_not_change_owner_decision(r0_pair, monkeypatch):
    version, rows, discovery = r0_pair
    monkeypatch.setattr(journey.sys, "platform", "win32")
    monkeypatch.setattr(journey, "healthy", lambda _: discovery)
    monkeypatch.setattr(journey.windows, "powershell", lambda *args, **kwargs: json.dumps(rows))
    def fail_capture(*args):
        raise OSError("capture failed")
    monkeypatch.setattr(journey, "_capture_windows_r0_selection_context", fail_capture)
    journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")
    rows[1]["ParentProcessId"] = 999
    with pytest.raises(RuntimeError, match="Expected exactly the selected Runtime owner"):
        journey.assert_release0_runtime(version.parent, version, version.parent / "evidence")
